// Night-flag weather station. A mast with a sensor panel at 1.45 m reads the
// live air temperature, logs it at the start of every Mars hour, and raises a
// red flag while the air is below -70 C. It logs the local hour of each crossing.
//
// ENV_AIR_TEMP_K is the typical air temperature at 1.45 m for the current local
// hour, averaged over one measured Mars year (Perseverance MEDA, MY36,
// jezero.temperature.my36_air_hourly_mean). It is not today's weather and has no
// seasons, so the flag rises and falls on the same schedule every sol.
// The -70 C threshold is the player's choice, not a fact about Mars.
import { read, fact, fact_tier, spawn, pose, remove, state_set, signal_emit, log,
         ENV_AIR_TEMP_K, ENV_LOCAL_HOUR, SHAPE_CYLINDER, SHAPE_PANEL, SHAPE_CONE,
         FACT_JEZERO_TEMPERATURE_MY36_AIR_HOURLY_MEAN,
         FACT_JEZERO_TEMPERATURE_MY36_AIR_DIURNAL_MIN } from "./host";

const SLOT_SOLS: i32 = 0;
const SLOT_T_K: i32 = 1;
const SLOT_T_C: i32 = 2;
const SLOT_FLAG: i32 = 3;
const SIGNAL_HOUR: i32 = 100;      // pulse at each new Mars hour, value = hour 0..23
const SIGNAL_NIGHT: i32 = 101;     // re-emitted every tick: 1 flag up, 0 flag down
const LOG_HOUR_TEMP: i32 = 30;     // value: air temperature at the start of the hour (K)
const LOG_TIER: i32 = 31;          // value: provenance tier of the hourly record
const LOG_FLAG_UP: i32 = 32;       // value: local hour the air dropped below -70 C
const LOG_FLAG_DOWN: i32 = 33;     // value: local hour the air rose back above -70 C
const LOG_NIGHT_MIN: i32 = 34;     // value: typical nightly minimum (K), read from the index
const KELVIN_OFFSET: f32 = 273.15; // unit conversion C <-> K, not a Mars number
const COLD_K: f32 = 203.15;        // -70 C: the player's threshold
const SENSOR_H: f32 = 1.45;        // MEDA air sensor height, as the live read states

let mast: i32 = -1, panel: i32 = -1, flag: i32 = -1;
let lastHour: i32 = -1;
let sols: i32 = 0;                 // midnights crossed since the station was placed
let flagUp: i32 = -1;              // -1 until the first reading

export function init(): void {
  mast = spawn(SHAPE_CYLINDER, 0.1, SENSOR_H, 0.1, 0.8, 0.8, 0.8);
  panel = spawn(SHAPE_PANEL, 0.4, 0.3, 0.05, 0.1, 0.3, 0.9);
  pose(mast, 0.0, SENSOR_H * 0.5, 0.0, 0.0, 0.0);
  pose(panel, 0.0, SENSOR_H, 0.0, 0.0, 0.3);
  // Provenance of the live read, plus the sourced nightly minimum for comparison.
  log(LOG_TIER, <f32>fact_tier(FACT_JEZERO_TEMPERATURE_MY36_AIR_HOURLY_MEAN));
  const nightMin = fact(FACT_JEZERO_TEMPERATURE_MY36_AIR_DIURNAL_MIN);
  if (nightMin == nightMin) log(LOG_NIGHT_MIN, nightMin); // skip if NaN
}

export function tick(dt: f32): void {
  const temp = read(ENV_AIR_TEMP_K);
  const hourNow = read(ENV_LOCAL_HOUR);      // same clock the temperature was looked up at
  state_set(SLOT_T_K, temp);
  state_set(SLOT_T_C, temp - KELVIN_OFFSET);

  const hour = <i32>Math.floor(hourNow);
  if (hour != lastHour) {
    if (lastHour >= 0 && hour < lastHour) sols += 1; // crossed midnight
    lastHour = hour;
    signal_emit(SIGNAL_HOUR, <f32>hour);
    log(LOG_HOUR_TEMP, temp);                // the hourly temperature log
  }
  state_set(SLOT_SOLS, <f32>sols + hourNow / 24.0);

  const cold: i32 = temp < COLD_K ? 1 : 0;
  if (cold != flagUp) {
    // Log real crossings only, not the first reading after placement.
    if (flagUp >= 0) log(cold == 1 ? LOG_FLAG_UP : LOG_FLAG_DOWN, hourNow);
    flagUp = cold;
    if (flag >= 0) { remove(flag); flag = -1; }
    if (cold == 1) {
      flag = spawn(SHAPE_CONE, 0.3, 0.4, 0.3, 1.0, 0.1, 0.1);
      pose(flag, 0.0, SENSOR_H + 0.4, 0.0, 0.0, 0.0);
    }
  }
  state_set(SLOT_FLAG, <f32>flagUp);
  signal_emit(SIGNAL_NIGHT, <f32>flagUp);    // held every tick so listeners never miss it
}

